(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-289":{scenario:{company:"Cao Nguyên Xanh Realty",supervisor:{name:"Lò Hoàng Nam",role:{vi:"Trưởng sàn Giao dịch Bất động sản",en:"Brokerage Floor Manager"}},ref_code:"BDS-4418",title:{vi:"Đúng pháp lý. Đúng lợi suất. Đúng khách hàng.",en:"Right title. Right yield. Right client."},brief:{vi:"Đây là tình huống đào tạo. Khách là cá nhân người nước ngoài, ngân sách tối đa 4,5 tỷ đồng, cần căn 2 phòng ngủ để cho thuê. Giỏ hàng: A-1205 (2PN, 4,2 tỷ, tòa A đã đủ hạn mức 30% căn hộ cho người nước ngoài), B-0807 (2PN, 4,4 tỷ, tòa B mới đạt 22%), C-1510 (3PN, 5,1 tỷ). Giá thuê dự kiến 18 triệu đồng/tháng. Sửa căn đề xuất và lợi suất cho thuê ròng (số liệu mô phỏng), rồi lập báo cáo tư vấn có căn cứ.",en:"This is a training scenario. The client is a foreign individual with a budget of up to 4.5 billion VND who needs a 2-bedroom unit to rent out. Inventory: A-1205 (2BR, 4.2 bn, Tower A already at the 30% foreign ownership cap), B-0807 (2BR, 4.4 bn, Tower B at 22%), C-1510 (3BR, 5.1 bn). Expected rent 18 million VND per month. Correct the recommended unit and the net rental yield (training figures), then write an evidence-based advisory report."},reference_title:{vi:"Hồ sơ pháp lý giỏ hàng & bảng phân tích dòng tiền đã duyệt · BDS-4418",en:"Approved inventory legal file & cash flow sheet · BDS-4418"},fields:[{id:"UNIT_CODE",label:{vi:"Căn hộ đề xuất",en:"Recommended unit"},initial:"A-1205",expected:"B-0807",choices:["A-1205","B-0807","C-1510"],reference:"Hồ sơ pháp lý giỏ hàng",hint:{vi:"Lọc theo ba điều kiện cùng lúc: số phòng ngủ, ngân sách và hạn mức sở hữu của người nước ngoài từng tòa.",en:"Filter on three conditions at once: bedrooms, budget and each tower's foreign ownership quota."}},{id:"NET_YIELD",label:{vi:"Lợi suất cho thuê ròng (%)",en:"Net rental yield (%)"},initial:"5.14",expected:"3.57",reference:"Bảng phân tích dòng tiền",ref_value:{vi:"Giá 4400 triệu; chi phí mua 2%; thuê 18 triệu x 11 tháng; thuế 10% doanh thu thuê; vận hành 18 triệu/năm",en:"Price 4400 million; purchase costs 2%; rent 18 million x 11 months; tax 10% of rent; operating 18 million/year"},hint:{vi:"Lợi suất gộp chưa trừ tháng trống, thuế, chi phí vận hành và chưa cộng chi phí mua vào vốn đầu tư.",en:"Gross yield ignores the vacant month, tax, operating costs and the purchase costs in the investment base."}}],sop32:{vi:"Lợi suất ròng (%) = (tiền thuê thu được 11 tháng/năm - thuế cho thuê 10% doanh thu - chi phí vận hành năm) / (giá mua + chi phí mua 2%) x 100, làm tròn 2 chữ số thập phân. Tỷ lệ trong bài là số liệu mô phỏng.",en:"Net yield (%) = (rent collected over 11 months - rental tax 10% of revenue - annual operating cost) / (price + 2% purchase costs) x 100, rounded to 2 decimals. Rates are training figures."},context:{label:"CRM / BDS-4418",metrics:[{label:{vi:"Ngân sách khách hàng",en:"Client budget"},value:"4.5 bn VND"},{label:{vi:"Hạn mức sở hữu nước ngoài",en:"Foreign ownership cap"},value:"30%"},{label:{vi:"Tỷ lệ đã dùng tòa B",en:"Tower B quota used"},value:"22%"},{label:{vi:"Giá thuê dự kiến",en:"Expected rent"},value:"18,000,000 VND"}]},crisis:{vi:"Đại diện chủ đầu tư nhắn: “Khách thích A-1205 thì cứ để một người Việt đứng tên hộ, ký thêm giấy ủy quyền riêng. Chốt cọc trong tuần này thì sàn được thưởng nóng.”",en:"The developer's representative messages you: “If the client likes A-1205, just put it under a Vietnamese nominee with a private power of attorney. Close the deposit this week and the floor gets a bonus.”"},options:{safe:{vi:"Từ chối phương án đứng tên hộ, giải thích rủi ro pháp lý cho khách và báo Trưởng sàn; đề xuất căn B-0807 còn hạn mức hoặc phương án thuê dài hạn hợp lệ.",en:"Refuse the nominee scheme, explain the legal risk to the client and inform the floor manager; propose B-0807 within quota or a lawful long-term lease."},shortcut:{vi:"Đồng ý cho người Việt đứng tên hộ để chốt cọc kịp nhận thưởng.",en:"Agree to the nominee arrangement to close the deposit and earn the bonus."},wait:{vi:"Không trả lời chủ đầu tư và để khách tự tìm cách mua căn A-1205.",en:"Ignore the developer and let the client find their own way to buy A-1205."}},questions:{vi:["Vì sao đề xuất B-0807 thay vì A-1205 hay C-1510? Căn cứ pháp lý và tiêu chí nào loại hai căn còn lại?","Trình bày cách tính lợi suất ròng và rủi ro cho khách nếu chỉ nhìn lợi suất gộp hoặc mua qua người đứng tên hộ."],en:["Why recommend B-0807 instead of A-1205 or C-1510? Which legal basis and criteria rule out the other two?","Explain the net yield calculation and the client's risk of relying on gross yield or buying through a nominee."]},hints:{vi:["Đặt bản nháp cạnh hồ sơ pháp lý giỏ hàng, kiểm tra tình trạng hạn mức sở hữu nước ngoài của từng tòa.","Tính theo SOP mục 3.2: thu nhập thực sau tháng trống, thuế và chi phí chia cho tổng vốn đầu tư.","Đọc lại SOP mục 4.2: không tư vấn lách luật; mọi đề nghị đứng tên hộ phải từ chối và báo cáo."],en:["Place the draft next to the inventory legal file and check each tower's foreign ownership quota.","Compute per SOP 3.2: real income after vacancy, tax and costs divided by the total investment.","Re-read SOP 4.2: never advise ways around the law; any nominee request must be refused and escalated."]}},learning:{summary:{vi:"Chuyên viên tư vấn và môi giới bất động sản giúp khách mua, bán, thuê hoặc đầu tư nhà đất: tìm hiểu mục tiêu tài chính, thẩm định pháp lý sản phẩm, phân tích giá và dòng tiền, dẫn xem thực tế, đàm phán và đồng hành đến khi ký hợp đồng, bàn giao. Nghề đòi hỏi nắm vững pháp luật đất đai, nhà ở, kinh doanh bất động sản, có chứng chỉ hành nghề và hoạt động qua doanh nghiệp dịch vụ môi giới, đặt quyền lợi hợp pháp của khách hàng lên trên hoa hồng.",en:"A real estate investment consultant helps clients buy, sell, lease or invest in property: clarifying financial goals, checking the legal status of products, analyzing price and cash flow, arranging viewings, negotiating and supporting clients through contract and handover. The role requires solid knowledge of land, housing and real estate business law, a practice certificate and work through a licensed brokerage firm, and putting the client's lawful interests above commission."},responsibilities:{vi:["Khảo sát nhu cầu, ngân sách, mục tiêu ở hay đầu tư và khẩu vị rủi ro của khách hàng.","Thẩm định pháp lý dự án, căn hộ: giấy chứng nhận, giấy phép xây dựng, điều kiện mở bán, bảo lãnh ngân hàng.","Phân tích giá so sánh, lợi suất cho thuê và dòng tiền vay vốn cho từng phương án.","Dẫn khách xem thực tế, đàm phán giá, điều khoản thanh toán và soạn thỏa thuận đặt cọc theo mẫu đã duyệt.","Theo dõi ký hợp đồng, thanh toán, bàn giao và chăm sóc khách sau giao dịch."],en:["Assess the client's needs, budget, live-in or investment goal and risk appetite.","Check project and unit legal status: certificates, building permit, sale conditions and bank guarantee.","Analyze comparable prices, rental yield and financed cash flow for each option.","Arrange viewings, negotiate price and payment terms and prepare deposit agreements on approved templates.","Follow contract signing, payments and handover, and care for clients after the deal."]},competencies:[{name:{vi:"Thẩm định pháp lý",en:"Legal due diligence"},desc:{vi:"Đọc giấy chứng nhận, quy hoạch, giấy phép và điều kiện chuyển nhượng, phát hiện rủi ro tranh chấp.",en:"Read certificates, zoning, permits and transfer conditions to spot dispute risks."}},{name:{vi:"Phân tích đầu tư",en:"Investment analysis"},desc:{vi:"Tính lợi suất gộp, ròng, dòng tiền vay và so sánh giá thị trường một cách thận trọng.",en:"Compute gross and net yield and financed cash flow and compare market prices prudently."}},{name:{vi:"Tư vấn & đàm phán",en:"Advisory & negotiation"},desc:{vi:"Lắng nghe mục tiêu khách, trình bày phương án rõ ràng và đàm phán điều khoản cân bằng.",en:"Listen to client goals, present options clearly and negotiate balanced terms."}},{name:{vi:"Hiểu biết thị trường",en:"Market knowledge"},desc:{vi:"Theo dõi nguồn cung, giá giao dịch, hạ tầng và chính sách tín dụng theo khu vực.",en:"Track supply, transaction prices, infrastructure and credit policy by area."}},{name:{vi:"Liêm chính & tuân thủ",en:"Integrity & compliance"},desc:{vi:"Không cam kết lợi nhuận, không tư vấn lách luật, nhận diện và báo cáo giao dịch đáng ngờ.",en:"Never guarantee returns or advise around the law; identify and report suspicious transactions."}}],knowledge:{vi:["Luật Kinh doanh bất động sản 2023: điều kiện hành nghề môi giới, chứng chỉ hành nghề và điều kiện bán nhà ở hình thành trong tương lai.","Luật Nhà ở 2023: quyền sở hữu nhà ở của tổ chức, cá nhân nước ngoài và hạn mức 30% số căn hộ mỗi tòa chung cư.","Luật Đất đai 2024: giấy chứng nhận, quy hoạch sử dụng đất và điều kiện chuyển nhượng.","Luật Phòng, chống rửa tiền 2022: nhận biết khách hàng và báo cáo giao dịch đáng ngờ trong kinh doanh bất động sản.","Phương pháp định giá so sánh, phương pháp thu nhập và chỉ số lợi suất gộp, lợi suất ròng."],en:["Real Estate Business Law 2023: brokerage practice conditions, practice certificates and conditions for selling off-plan housing.","Housing Law 2023: foreign ownership rights and the 30% cap on apartments per building.","Land Law 2024: land use certificates, land use planning and transfer conditions.","Anti-Money Laundering Law 2022: customer due diligence and suspicious transaction reporting in real estate.","Sales comparison and income valuation methods and gross versus net yield."]},tools:["Hệ thống CRM bất động sản","Phần mềm quản lý giỏ hàng","Bảng tính phân tích dòng tiền","Bản đồ quy hoạch trực tuyến","Công cụ tham quan ảo 360 độ"],kpis:{vi:["Số giao dịch thành công và giá trị giao dịch mỗi quý.","Tỷ lệ chuyển đổi từ khách xem nhà sang đặt cọc.","Tỷ lệ hủy cọc hoặc khiếu nại do tư vấn sai (mục tiêu bằng 0).","Điểm hài lòng và tỷ lệ khách giới thiệu khách mới."],en:["Closed deals and transaction value per quarter.","Viewing-to-deposit conversion rate.","Deposit cancellations or complaints caused by wrong advice (target zero).","Satisfaction score and referral rate."]},day:[{time:"08:30",vi:"Cập nhật tin thị trường, giỏ hàng và tình trạng hạn mức sở hữu nước ngoài từng tòa.",en:"Update market news, inventory and each tower's foreign ownership quota."},{time:"10:00",vi:"Dẫn khách xem căn hộ mẫu và tiện ích thực tế của dự án.",en:"Show a client the model unit and the project's actual amenities."},{time:"13:30",vi:"Lập bảng phân tích dòng tiền, lợi suất cho từng căn trong danh sách rút gọn.",en:"Build cash flow and yield sheets for each shortlisted unit."},{time:"15:30",vi:"Kiểm tra pháp lý dự án: giấy phép xây dựng, bảo lãnh ngân hàng, văn bản đủ điều kiện bán.",en:"Check project legal papers: building permit, bank guarantee and sale eligibility notice."},{time:"17:30",vi:"Cập nhật CRM, gửi báo cáo tư vấn và lịch hẹn tiếp theo cho khách.",en:"Update the CRM and send the advisory report and next appointment to the client."}],mistakes:{vi:["Đề xuất căn ở tòa đã đủ hạn mức sở hữu cho khách nước ngoài.","Quảng cáo lợi suất gộp như lợi nhuận thực, bỏ qua tháng trống, thuế và chi phí.","Hứa cam kết lợi nhuận hoặc tư vấn đứng tên hộ để chốt giao dịch nhanh."],en:["Recommending a unit in a tower whose foreign quota is already full.","Selling gross yield as real profit while ignoring vacancy, tax and costs.","Guaranteeing returns or suggesting nominee ownership to close faster."]},career:[{vi:"Cộng tác viên / thực tập sinh môi giới",en:"Brokerage trainee"},{vi:"Chuyên viên tư vấn bất động sản (có chứng chỉ hành nghề)",en:"Licensed real estate consultant"},{vi:"Trưởng nhóm kinh doanh sàn giao dịch",en:"Brokerage sales team lead"},{vi:"Giám đốc sàn / Giám đốc tư vấn đầu tư bất động sản",en:"Brokerage or real estate investment director"}],glossary:[{term:"Net yield",vi:"Lợi suất ròng: thu nhập cho thuê sau thuế, chi phí và tháng trống chia cho tổng vốn đầu tư.",en:"Rental income after tax, costs and vacancy divided by the total investment."},{term:"Thông thủy",vi:"Diện tích sử dụng căn hộ tính theo kích thước thông thủy, dùng ghi trong hợp đồng mua bán.",en:"Net usable floor area of an apartment, used in the sale contract."},{term:"Off-plan",vi:"Nhà ở hình thành trong tương lai: đang xây dựng, chưa nghiệm thu đưa vào sử dụng.",en:"Housing still under construction and not yet accepted for use."},{term:"Đặt cọc",vi:"Khoản tiền bảo đảm giao kết hoặc thực hiện hợp đồng, có điều khoản phạt cọc rõ ràng.",en:"A deposit securing the signing or performance of a contract, with clear forfeiture terms."},{term:"KYC",vi:"Nhận biết khách hàng: xác minh danh tính, nguồn tiền theo quy định phòng, chống rửa tiền.",en:"Know your customer: verifying identity and source of funds under anti-money laundering rules."}],quiz:[{q:{vi:"Căn hộ giá 3000 triệu đồng, cho thuê 15 triệu đồng/tháng đủ 12 tháng. Lợi suất gộp là bao nhiêu?",en:"A unit costs 3000 million VND and rents for 15 million VND per month for 12 months. What is the gross yield?"},options:{vi:["5%","6%","6,5%","7,2%"],en:["5%","6%","6.5%","7.2%"]},answer:1,explain:{vi:"15 x 12 = 180 triệu; 180 / 3000 = 6%. Lợi suất ròng sẽ thấp hơn sau thuế, chi phí và tháng trống.",en:"15 x 12 = 180 million; 180 / 3000 = 6%. Net yield is lower after tax, costs and vacancy."}},{q:{vi:"Theo Luật Nhà ở, tổ chức, cá nhân nước ngoài được sở hữu tối đa bao nhiêu phần trăm số căn hộ trong một tòa chung cư?",en:"Under the Housing Law, what share of apartments in one building may foreign entities and individuals own at most?"},options:{vi:["10%","20%","30%","50%"],en:["10%","20%","30%","50%"]},answer:2,explain:{vi:"Hạn mức là 30% số căn hộ của một tòa nhà chung cư; khi tòa đã đủ, người nước ngoài không mua thêm được.",en:"The cap is 30% of the apartments in a building; once reached, foreigners cannot buy more there."}},{q:{vi:"Khách nước ngoài muốn mua căn ở tòa đã đủ hạn mức và đề nghị nhờ người Việt đứng tên hộ. Bạn làm gì?",en:"A foreign client wants a unit in a tower at its quota and suggests a Vietnamese nominee. What do you do?"},options:{vi:["Từ chối, giải thích rủi ro pháp lý và đề xuất căn còn hạn mức","Giới thiệu người đứng tên quen biết","Đồng ý nếu khách ký cam kết tự chịu","Im lặng để khách tự xử lý"],en:["Refuse, explain the legal risk and offer a unit within quota","Introduce a nominee you know","Agree if the client signs a waiver","Stay silent and let the client handle it"]},answer:0,explain:{vi:"Đứng tên hộ là lách luật, khách có thể mất tài sản khi tranh chấp; môi giới phải tư vấn phương án hợp pháp.",en:"Nominee ownership circumvents the law and the client may lose the asset in a dispute; advise lawful options."}},{q:{vi:"Diện tích căn hộ ghi trong hợp đồng mua bán theo quy định hiện hành là diện tích nào?",en:"Under current rules, which area is stated in an apartment sale contract?"},options:{vi:["Diện tích tim tường","Diện tích sàn xây dựng toàn tòa","Diện tích có ban công tính gấp đôi","Diện tích sử dụng tính theo kích thước thông thủy"],en:["Wall-centerline area","Gross floor area of the building","Area with balconies counted twice","Net usable area measured wall to wall"]},answer:3,explain:{vi:"Hợp đồng mua bán căn hộ ghi diện tích sử dụng thông thủy; tư vấn giá trên diện tích tim tường dễ gây hiểu nhầm.",en:"Apartment contracts state the net usable area; quoting price on centerline area misleads clients."}}],tools_en:["Real estate CRM system","Unit inventory management software","Cash flow analysis spreadsheet","Online land-use planning map","360-degree virtual tour tools"]}}})})(window.KKR);
